const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Paraná River delta region (Argentina)
  const parana = ee.Geometry.Polygon([
    [[-60.8, -34.5], [-60.8, -32.5], [-58.0, -32.5], [-58.0, -34.5], [-60.8, -34.5]]
  ]);

  // Date ranges
  const start2019 = '2019-01-01';
  const end2019 = '2019-07-22';
  const start2020 = '2020-01-01';
  const end2020 = '2020-07-22';

  // Use MODIS Thermal Anomalies/Fire Daily product
  const fires2019 = ee.ImageCollection('MODIS/061/MOD14A1')
    .filterDate(start2019, end2019)
    .filterBounds(parana)
    .select('MaxFRP'); // Maximum Fire Radiative Power

  const fires2020 = ee.ImageCollection('MODIS/061/MOD14A1')
    .filterDate(start2020, end2020)
    .filterBounds(parana)
    .select('MaxFRP');

  // Check if collections have data
  const size2019 = fires2019.size().getInfo();
  const size2020 = fires2020.size().getInfo();

  console.log(`2019 Images: ${size2019}`);
  console.log(`2020 Images: ${size2020}`);

  if (size2019 === 0 || size2020 === 0) {
    console.log('Missing data for one or both periods');
    console.log('<answer>C1</answer>');
    return;
  }

  // Count fire pixels (MaxFRP > 0 indicates fire detection)
  const countFires = function(collection) {
    const composite = collection.max(); // Get maximum FRP across all dates
    const firePixels = composite.gt(0); // Pixels with fire detection

    const stats = firePixels.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: parana,
      scale: 1000,
      maxPixels: 1e9
    });

    return stats.get('MaxFRP');
  };

  // Calculate fire hotspot counts
  const count2019 = countFires(fires2019).getInfo();
  const count2020 = countFires(fires2020).getInfo();

  console.log(`2019 Fire Hotspots: ${count2019}`);
  console.log(`2020 Fire Hotspots: ${count2020}`);

  // Validate results
  if (count2019 === null || count2020 === null || 
      isNaN(count2019) || isNaN(count2020)) {
    console.log('Calculation failed - invalid result');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare fire counts
  if (count2020 > count2019) {
    console.log(`2020 exceeds 2019: ${count2020} > ${count2019}`);
    console.log('<answer>A</answer>');
  } else {
    console.log(`2020 does not exceed 2019: ${count2020} <= ${count2019}`);
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
